#!/bin/bash

echo "### 1. agent_run表结构 + 最近任务步数 ###"
MP=$(docker exec coze-mysql printenv MYSQL_ROOT_PASSWORD)
echo "--- agent_run相关表 ---"
docker exec coze-mysql mysql -uroot -p"$MP" opencoze -N -e "
SELECT table_name FROM information_schema.tables WHERE table_schema='opencoze' AND table_name LIKE '%run%';" 2>/dev/null

echo ""
echo "--- 查含step/iteration字段的列 ---"
docker exec coze-mysql mysql -uroot -p"$MP" opencoze -N -e "
SELECT table_name, column_name FROM information_schema.columns 
WHERE table_schema='opencoze' AND (column_name LIKE '%step%' OR column_name LIKE '%iteration%') 
LIMIT 20;" 2>/dev/null

echo ""
echo "### 2. 并发视频实测（脚本base64内嵌）###"
echo "" | base64 -d > /tmp/conc_run.py
# /tmp 在容器里挂载为 /host-tmp
docker exec tool-proxy python3 /host-tmp/conc_run.py 2>&1

echo ""
echo "### 3. submit日志 ###"
docker logs tool-proxy --since 3m 2>&1 | grep "\[VID\] submit" | tail -6

echo "[DONE]"
